def _detect_device(device: str | None = None) -> str:
    """
    Resolve the device to use for inference.

    If ``device`` is explicitly provided, it is returned unchanged. Otherwise the value of the
    ``MLFLOW_DEFAULT_PREDICTION_DEVICE`` environment variable is used.
    """
    if device is not None:
        return device

    from mlflow.environment_variables import MLFLOW_DEFAULT_PREDICTION_DEVICE

    return MLFLOW_DEFAULT_PREDICTION_DEVICE.get()


def _image_to_png_bytes(image) -> bytes:
    buffer = io.BytesIO()
    image.save(buffer, format="PNG")
    return buffer.getvalue()


class _DiffusersAdapterWrapper:
    """PyFunc wrapper for diffusion model adapters."""

    def __init__(self, adapter_path: str, flavor_conf: dict, model_config: dict | None = None):
        self.adapter_path = adapter_path
        self._flavor_conf = flavor_conf
        self.model_config = model_config or {}
        self._pipeline = None

    def _load_pipeline(self):
        if self._pipeline is not None:
            return self._pipeline

        import diffusers

        base_model = self.model_config.get("base_model") or self._flavor_conf["base_model"]

        try:
            pipeline = diffusers.DiffusionPipeline.from_pretrained(base_model)
        except OSError as e:
            raise MlflowException(
                f"Failed to load base model '{base_model}': {e}"
            ) from e

        weight_name = self._flavor_conf.get("weight_name")
        load_kwargs = {"weight_name": weight_name} if weight_name else {}
        pipeline.load_lora_weights(self.adapter_path, **load_kwargs)

        device = _detect_device(self.model_config.get("device"))
        if device:
            pipeline = pipeline.to(device)

        self._pipeline = pipeline
        return self._pipeline

    def get_raw_model(self):
        """Return the underlying diffusion pipeline."""
        return self._load_pipeline()

    def _extract_prompts(self, data) -> list[str]:
        import pandas as pd

        if isinstance(data, str):
            prompts = [data]
        elif isinstance(data, dict):
            if "prompt" not in data:
                raise MlflowException(
                    "Input dictionary must contain a 'prompt' key.",
                    error_code=INVALID_PARAMETER_VALUE,
                )
            value = data["prompt"]
            if isinstance(value, str):
                prompts = [value]
            elif isinstance(value, list):
                prompts = list(value)
            else:
                raise MlflowException(
                    "The 'prompt' value must be a string or list of strings.",
                    error_code=INVALID_PARAMETER_VALUE,
                )
        elif isinstance(data, pd.DataFrame):
            if "prompt" in data.columns:
                prompts = data["prompt"].tolist()
            elif len(data.columns) == 1:
                prompts = data.iloc[:, 0].tolist()
            else:
                raise MlflowException(
                    "Input DataFrame must contain a 'prompt' column.",
                    error_code=INVALID_PARAMETER_VALUE,
                )
        elif isinstance(data, list):
            prompts = list(data)
        else:
            raise MlflowException(
                f"Unsupported input type: {type(data)}. Supported types are string, list of "
                "strings, dict with a 'prompt' key, or a pandas DataFrame.",
                error_code=INVALID_PARAMETER_VALUE,
            )

        if len(prompts) == 0:
            raise MlflowException(
                "No prompts were provided for inference.",
                error_code=INVALID_PARAMETER_VALUE,
            )

        if any(p is None for p in prompts):
            raise MlflowException(
                "All prompt values must be strings, not None.",
                error_code=INVALID_PARAMETER_VALUE,
            )

        return prompts

    def predict(self, data, params: dict[str, Any] | None = None) -> list[bytes]:
        prompts = self._extract_prompts(data)

        pipeline = self._load_pipeline()

        call_kwargs = dict(params) if params else {}
        output = pipeline(prompt=prompts, **call_kwargs)

        images = getattr(output, "images", None)
        if images is None or len(images) == 0:
            raise MlflowException(
                "Pipeline returned no images.",
                error_code=INVALID_PARAMETER_VALUE,
            )

        return [_image_to_png_bytes(image) for image in images]
